local function C_f()
	local script = LMG2L["LocalScript_f"];
	local button = script.Parent	
	button.MouseButton1Click:Connect(function()	
		local player = game.Players.LocalPlayer	
		local char = player.Character	
		local tool	

		for i,v in player:GetDescendants() do	
			if v.Name == "SyncAPI" then tool = v.Parent end	
		end	
		for i,v in game.ReplicatedStorage:GetDescendants() do	
			if v.Name == "SyncAPI" then tool = v.Parent end	
		end	

		remote = tool.SyncAPI.ServerEndpoint	
		function _(args) remote:InvokeServer(unpack(args)) end	
		function SetAnchor(boolean,part) _({[1] = "SyncAnchor", [2] = {[1] = {["Part"] = part, ["Anchored"] = boolean}}}) end		
		function CreatePart(cf,parent) _({[1] = "CreatePart", [2] = "Normal", [3] = cf, [4] = parent}) end	
		function SetMesh(part,meshid) _({[1] = "SyncMesh", [2] = {[1] = {["Part"] = part, ["MeshId"] = "rbxassetid://"..meshid}}}) end	
		function SetTexture(part, texid) _({[1] = "SyncMesh", [2] = {[1] = {["Part"] = part, ["TextureId"] = "rbxassetid://"..texid}}}) end	
		function SetName(part, stringg) _({[1] = "SetName", [2] = {[1] = part}, [3] = stringg}) end	
		function MeshResize(part,size) _({[1] = "SyncMesh", [2] = {[1] = {["Part"] = part, ["Scale"] = size}}}) end	
		function SetLocked(part,boolean) _({[1] = "SetLocked", [2] = {[1] = part}, [3] = boolean}) end	
		function AddMesh(part) _({[1] = "CreateMeshes", [2] = {[1] = {["Part"] = part}}}) end

		function Sky(id)	
			local root = char:WaitForChild("HumanoidRootPart")	
			local pos = root.CFrame + Vector3.new(0, 6, 0)	
			CreatePart(pos, workspace)	
			task.wait(0.2)	
			local skyPart	
			for _, v in workspace:GetChildren() do	
				if v:IsA("BasePart") and (v.Position - pos.Position).magnitude < 1 then	
					skyPart = v	
					break	
				end	
			end	
			if skyPart then	
				SetName(skyPart, "Sky")	
				AddMesh(skyPart)	
				SetMesh(skyPart, "111891702759441")	
				SetTexture(skyPart, id)	
				MeshResize(skyPart, Vector3.new(4000, 4000, 4000))	
				SetLocked(skyPart, true)	
				SetAnchor(true, skyPart)	
			end	
		end	

		Sky("103954675468146")	
	end)	
end;
task.spawn(C_f);

